sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float blurLength;
uniform float angle;

half4 main(float2 coord) {
    float rad = radians(angle);
    float2 dir = float2(cos(rad), sin(rad));
    half4 accum = half4(0.0);
    for (int i = 0; i < 32; ++i) {
        float t = float(i) / 31.0;
        float2 offset = dir * t * blurLength;
        float2 sampleCoord = coord - offset;
        half4 c = image.eval(sampleCoord);
        float a = c.a;
        if (a > 0.001) {
            c.rgb /= a;
        }
        accum += c;
    }
    accum /= 32.0;
    accum.rgb *= accum.a;
    return accum;
}
